// ToDomain maps a slice of ent LineItem to billingdomain.LineItemList.
func (es LineItems) ToDomain() billingdomain.LineItemList {
	ds := make(billingdomain.LineItemList, len(es))
	for i, e := range es {
		ds[i] = e.ToDomain()
	}
	return ds
}

// CreateBulkDomain creates a LineItemCreateBulk from billingdomain.LineItemList.
//
// If any per-row transformer returns an error, the first such error is
// returned immediately and partial bulk is discarded.
func (c *LineItemClient) CreateBulkDomain(ctx context.Context, ds billingdomain.LineItemList, opts ...entdomain.ApplyOption) (*LineItemCreateBulk, error) {
	builders := make([]*LineItemCreate, len(ds))
	for i := range ds {
		if ds[i] == nil {
			return nil, fmt.Errorf("CreateBulkDomain: nil LineItem at index %d", i)
		}
		b, err := c.Create().ApplyDomain(ctx, ds[i], opts...)
		if err != nil {
			return nil, err
		}
		builders[i] = b
	}
	return c.CreateBulk(builders...), nil
}

